<?php require __DIR__.'/includes/bootstrap.php';require_login();$id=trim((string)($_GET['id']??''));if($id===''||!ctype_digit($id)){http_response_code(400);exit('Invalid order ID.');}$brand=current_brand();$order=null;$error='';$start=$_GET['start']??date('Y-m-d');$end=$_GET['end']??date('Y-m-d');if(!$brand){$error='No brand is selected.';}else{try{foreach(sticky_orders($brand,$start,$end) as $o)if((string)($o['order_id']??'')===$id){$order=$o;break;}if(!$order)$error='Order was not returned by Sticky.io for this brand and date range. Try a wider date range.';}catch(Throwable $e){$error=$e->getMessage();}}$pageTitle='Order Details';require __DIR__.'/includes/header.php';?><div class="section-title"><h1>Order Details</h1><a class="btn secondary" href="dashboard.php?start=<?=e($start)?>&end=<?=e($end)?>">Back to reports</a></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php elseif($order):?><section class="panel"><h2>Order #<?=e($id)?></h2><p>Classification: <strong><?=e(classify_order($order))?></strong></p><div class="table-wrap"><table><tbody><?php foreach($order as $key=>$value):?><tr><th><?=e($key)?></th><td class="detail"><?php if(is_array($value)):?><pre><?=e(json_encode($value,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES))?></pre><?php else:?><?=e($value)?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php require __DIR__.'/includes/footer.php'; ?>